from pathlib import Path
import json,hashlib,datetime
root=Path(__file__).resolve().parents[5];b=Path(__file__).resolve().parent
h=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
freeze=b/'PRE-CANDIDATE-FREEZE.json';f=json.loads(freeze.read_text())
for p,d in f['file_hashes'].items():assert h(root/p)==d,p
r=root/'research/rmaf/results/algorithm-whole-source-work-fresh-review-controls-v1.json';x=json.loads(r.read_text());assert x['cases']==34 and x['plants_caught']==93
preserved=sum(p['value_preserved'] for row in x['rows'] for p in row['plants'])
receipt={'status':'READY-FOR-SEPARATE-ROOT-EXACT-RELEASE','created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'pre_candidate_freeze_sha256':h(freeze),'instrument_sha256':h(b/'caller_ledger.py'),'control_pin_sha256':h(b/'CONTROL-PIN.json'),'reused_core_ledger_sha256':h(b/'core_ledger.py'),'clean_cases_passed':34,'corrupt_twins_caught':93,'corrupt_reports_preserving_values':preserved,'fixed_battery_seconds':x['seconds'],'source_contact_scope':'root target/main target,frozen original geometry/CoreProgram/RMAF,own corrected core-cost material only','candidate_content_or_compilations':0,'children_in_preparation':0,'author_messaging':False,'independent_replications_added':0,'reference_numeric_encoding_not_predicted_candidate':True,'raw_output_dedup_diagnostic_not_assumed_2q_cost':True,'kernel_plants':'preregistered but UNEXECUTED until release','all_three_main_milestones':'OPEN'}
(b/'PRE-CANDIDATE-RECEIPT.json').write_text(json.dumps(receipt,indent=2)+'\n')
ready=f'''# Readiness receipt\n\nREADY for a separate exact root release. No candidate content was read or compiled; no preparation child or author contact. All three milestones OPEN; same reviewer lineage, zero extra replications.\n\n- Frozen34 clean cases passed and93 corrupt twins caught ({preserved} preserve returned values).\n- Tiny3+4 pilots measured before the fixed battery; full battery0.022611458s. Measurements certify this configuration only.\n- PRE-CANDIDATE-FREEZE SHA `{h(freeze)}`.\n- Instrument SHA `{h(b/'caller_ledger.py')}`; literal control pin SHA `{h(b/'CONTROL-PIN.json')}`.\n- Reused prior independent core ledger SHA `{h(b/'core_ledger.py')}`, explicitly same lineage. New graph/paths/callback/list instrument uses no candidate/prover code.\n- Full-origin/private/generated/unused-custom-axiom and explicit false/import/clean kernel gates are frozen and unexecuted.\n\nThe controls cover parent membership, original leaf lookup/regions/joint colors and collision/residue traps, empty/singleton/root/refusal/oversized encoding, leafless joint count, selectors,3/4/2 alternative and generation identities, unchanged ordinary q, callback calls versus evaluation work, repeated raw outputs, both outer append spines with multiplier8, literal dedup demands and missing/duplicate records.\n\nCandidate exact encodings and append/dedup implementation remain unknown. The canonical code and single-callback scheduling fixtures are independent diagnostics, not predicted candidate source. On release every actual source interface must be reconstructed and related to these pinned constraints; new required premises stay open until derived. COST-BOUNDARY-AMENDMENT-v1 explicitly distinguishes polynomial joint-color dedup from potentially exponential-factor raw-output dedup. Formal meter/value projection remains separate from source-operation contracts and compiler/machine bounds.\n\nThe192-file prior core-work review is preserved; only its manifest identity was rechecked during this preparation. Wait for root's separate exact release; do not self-release from the administratively known author freeze.\n'''
(b/'READY.md').write_text(ready)
paths=[p for p in b.rglob('*') if p.is_file() and '__pycache__' not in p.parts and p.name!='READY-ARTIFACTS.json']
paths+=[p for p in (root/'research/rmaf/results').glob('algorithm-whole-source-work-fresh-review-*') if p.is_file()]
paths=sorted(set(paths));out={'created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'immutable pre-candidate readiness; candidate review uses NEW phase files only','file_hashes':{str(p.relative_to(root)):h(p) for p in paths},'manifest_excludes_itself_and_python_caches':True,'candidate_contact':False}
p=b/'READY-ARTIFACTS.json';p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'readiness_files':len(paths),'readiness_manifest_sha256':h(p),'pre_candidate_freeze_sha256':h(freeze),'value_preserving_corrupt_reports':preserved,'candidate_contact':False}))
